package com.pp.shaderlod.lod.terrain;import com.mojang.brigadier.CommandDispatcher;import com.mojang.brigadier.arguments.IntegerArgumentType;
public final class GeometryLodCommands{public static void register(CommandDispatcher<net.minecraft.commands.CommandSourceStack> d){d.register(com.mojang.brigadier.builder.LiteralArgumentBuilder.<net.minecraft.commands.CommandSourceStack>literal("shaderlod").then(com.mojang.brigadier.builder.LiteralArgumentBuilder.<net.minecraft.commands.CommandSourceStack>literal("terrain").then(com.mojang.brigadier.builder.LiteralArgumentBuilder.<net.minecraft.commands.CommandSourceStack>literal("confirm").executes(c->{boolean ok=GeometryLodController.confirmCurrentScene();if(ok)c.getSource().sendSuccess(()->net.minecraft.network.chat.Component.literal("DH replacement coverage confirmed for this scene."),false);else c.getSource().sendFailure(net.minecraft.network.chat.Component.literal(GeometryLodController.confirmationReason()));return ok?1:0;})).then(com.mojang.brigadier.builder.LiteralArgumentBuilder.<net.minecraft.commands.CommandSourceStack>literal("revoke").executes(c->{GeometryLodController.revokeCurrentScene();return 1;})).then(com.mojang.brigadier.builder.LiteralArgumentBuilder.<net.minecraft.commands.CommandSourceStack>literal("cap").then(com.mojang.brigadier.builder.RequiredArgumentBuilder.<net.minecraft.commands.CommandSourceStack,Integer>argument("chunks",IntegerArgumentType.integer(8,32)).executes(c->{GeometryLodController.setCap(IntegerArgumentType.getInteger(c,"chunks"));return 1;})))));}}
